INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000245',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of technology at B2","Use Technologiegeschichte vocabulary","Talk about key inventions and their social impact"],"explanation":{"intro":"History of technology vocabulary covers major inventions, technological transitions, and the relationship between technology and society at B2.","culturalNote":"Technologiegeschichte: key inventions with German connection: Buchdruckmaschine (Gutenberg printing press 1450 — Mainz), Automobil (Benz Patent-Motorwagen 1885, Daimler), Dieselmotor (Rudolf Diesel 1897), Röntgenstrahlen (X-rays — Wilhelm Röntgen 1895), MP3 (Fraunhofer Institute 1989). Broader: Dampfmaschine (steam engine), Elektrizität (electricity — Edison, Tesla), Internet (ARPANET 1969). Key concept: technologischer Paradigmenwechsel (technological paradigm shift — Kuhn)."},"examples":[{"german":"Gutenbergs Buchdruck war eine technologische Revolution, die das Informationsmonopol der Kirche und der Gelehrten brach und die Grundlage für Reformation, Renaissance und Aufklärung legte.","english":"Gutenberg''s printing press was a technological revolution that broke the information monopoly of the Church and the learned and laid the foundation for the Reformation, Renaissance, and Enlightenment."},{"german":"Technologien sind keine neutralen Werkzeuge, sondern verändern die sozialen Verhältnisse, in denen sie entstehen, und eröffnen neue Möglichkeitsräume, während sie andere verschließen.","english":"Technologies are not neutral tools, but change the social relations in which they arise and open up new spaces of possibility while closing others off."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss the history of technology, key German inventions, and technology''s social impact at B2."}}',
'{"items":[{"word":"das Monopol","translation":"monopoly","pronunciation":"dahs mo-no-POHL","example":"Informationsmonopol."},{"word":"legen","translation":"to lay (a foundation)","pronunciation":"LAY-gen","example":"Die Grundlage legen."},{"word":"der Möglichkeitsraum","translation":"space of possibility","pronunciation":"dayr MÖG-likh-kyts-rowm","example":"Neue Möglichkeitsräume."},{"word":"verschließen","translation":"to close off","pronunciation":"fer-SHLEE-sen","example":"Möglichkeiten verschließen."},{"word":"das Paradigma","translation":"paradigm","pronunciation":"dahs pah-rah-DIG-mah","example":"Technologisches Paradigma."},{"word":"neutral","translation":"neutral","pronunciation":"noy-TRAHL","example":"Keine neutralen Werkzeuge."}]}',
'{"title":"Neue Möglichkeitsräume eröffnen — to open up new spaces of possibility","pattern":"etwas eröffnet neue Möglichkeiten/Möglichkeitsräume = something opens up new possibilities/spaces of possibility","explanation":"Neue Möglichkeitsräume eröffnen = to open up new spaces of possibility (Möglichkeitsraum — compound: Möglichkeit + Raum — space of possibility, metaphor for conceptual space). Eröffnen = to open (more formal/deliberate than aufmachen). Also: Perspektiven eröffnen (to open up perspectives), Chancen eröffnen (to open up opportunities), Wege eröffnen (to open up paths). Compare: ermöglichen (to make possible — less metaphorical), schaffen (to create — more active), bereitstellen (to provide — more literal).","examples":[{"sentence":"Die neue Technologie eröffnet völlig neue Möglichkeitsräume für die Medizin.","translation":"The new technology opens up entirely new spaces of possibility for medicine."},{"sentence":"Das Stipendium eröffnete ihr Wege, die sie sonst nie hätte gehen können.","translation":"The scholarship opened up paths for her that she could otherwise never have taken."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Das Monopol'' means?","options":["monopoly","exclusive right","dominance","sole control"],"correctAnswer":"monopoly"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Gutenberg''s printing press was a technological revolution that broke the information monopoly of the Church and the learned and laid the foundation for the Reformation, Renaissance, and Enlightenment.","options":["Gutenbergs Buchdruck war eine technologische Revolution, die das Informationsmonopol der Kirche und der Gelehrten brach und die Grundlage für Reformation, Renaissance und Aufklärung legte.","Der Buchdruck revolutionierte die Verbreitung von Informationen.","Gutenbergs Erfindung ermöglichte die Verbreitung von Wissen und bereitete den Weg für die Moderne.","Der Buchdruck brach das Wissensmonopol und veränderte die europäische Gesellschaft."],"correctAnswer":"Gutenbergs Buchdruck war eine technologische Revolution, die das Informationsmonopol der Kirche und der Gelehrten brach und die Grundlage für Reformation, Renaissance und Aufklärung legte."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die neue Technologie eröffnet völlig neue Möglichkeitsräume für die ___.","options":["Medizin","Wissenschaft","Gesellschaft","Forschung"],"correctAnswer":"Medizin"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The scholarship opened up paths for her that she could otherwise never have taken","wordBankItems":["Das","Stipendium","eröffnete","ihr","Wege",",","die","sie","sonst","nie","hätte","gehen","können","."],"correctAnswer":"Das Stipendium eröffnete ihr Wege , die sie sonst nie hätte gehen können ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verschließen'' means?","options":["to close off","to shut","to seal","to block"],"correctAnswer":"to close off"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000246',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss print and media history at B2","Use Drucktechnik vocabulary","Talk about media revolutions and public sphere"],"explanation":{"intro":"Print and media history vocabulary covers printing technology, the rise of mass media, and the digital transformation at B2.","culturalNote":"Mediengeschichte: Gutenberg 1450 (movable type — revolutionised knowledge distribution), periodische Presse (18th century), Massenmedien (mass media — 19th/20th century: Telegraf, Telefon, Radio, Film, Fernsehen), digitale Revolution (internet, social media). German context: Rundfunkstaatsvertrag (broadcasting state treaty — regulates public broadcasting: ARD, ZDF, ORF), Pressefreiheit (press freedom — GG Art. 5), Medienpluralismus (media pluralism). Key debate: Öffentlichkeit (public sphere — Habermas), Algorithmen und Filterblasen (algorithms and filter bubbles)."},"examples":[{"german":"Die Entwicklung der Massenpresse im 19. Jahrhundert schuf eine neue Form der Öffentlichkeit, die politische Partizipation demokratisierte, gleichzeitig aber auch Massenmobilisierung für Propaganda ermöglichte.","english":"The development of the mass press in the 19th century created a new form of public sphere that democratised political participation, but at the same time also enabled mass mobilisation for propaganda."},{"german":"Soziale Medien versprechen eine Demokratisierung der Öffentlichkeit, schaffen jedoch durch algorithmische Selektion Filterblasen, die homogene Meinungsmilieus verstärken.","english":"Social media promise a democratisation of the public sphere, but through algorithmic selection create filter bubbles that reinforce homogeneous opinion milieus."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss media history, the public sphere, and filter bubbles at B2."}}',
'{"items":[{"word":"die Partizipation","translation":"participation","pronunciation":"dee par-ti-tsi-pah-TSYOHN","example":"Politische Partizipation."},{"word":"die Massenmobilisierung","translation":"mass mobilisation","pronunciation":"dee MA-sen-mo-bi-li-ZEER-oong","example":"Massenmobilisierung ermöglichen."},{"word":"algorithmisch","translation":"algorithmic","pronunciation":"al-go-RIT-mish","example":"Algorithmische Selektion."},{"word":"die Filterblase","translation":"filter bubble","pronunciation":"dee FIL-ter-blah-seh","example":"Filterblasen schaffen."},{"word":"verstärken","translation":"to reinforce/amplify","pronunciation":"fer-SHTER-ken","example":"Meinungsmilieus verstärken."},{"word":"das Milieu","translation":"milieu/environment","pronunciation":"dahs mi-LYOH","example":"Homogene Meinungsmilieus."}]}',
'{"title":"Gleichzeitig aber auch — simultaneously but also (adding a second, often contrasting, simultaneous effect)","pattern":"Haupt-clause, gleichzeitig aber auch Haupt-clause = simultaneously but also (both effects happening at the same time — one often positive, one negative)","explanation":"Gleichzeitig aber auch = simultaneously but also (marks that a second, often contrasting effect is occurring at the same time as the first — temporal and logical connection). Die Presse demokratisierte, ermöglichte gleichzeitig aber auch Propaganda = democratised participation but also simultaneously enabled propaganda. Common in analytical writing describing dual/ambivalent effects. Compare: andererseits (on the other hand — contrasts at a higher level, not necessarily simultaneous), zugleich (at the same time — more literary, less colloquial), nichtsdestotrotz (nevertheless — more adversative), allerdings (however — often concessive).","examples":[{"sentence":"Das Medikament lindert die Symptome, hat gleichzeitig aber auch Nebenwirkungen.","translation":"The medication relieves the symptoms but simultaneously also has side effects."},{"sentence":"Die Reform verbesserte die Effizienz, erhöhte gleichzeitig aber auch die Ungleichheit.","translation":"The reform improved efficiency, but simultaneously also increased inequality."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Filterblase'' means?","options":["filter bubble","echo chamber","information silo","content bubble"],"correctAnswer":"filter bubble"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Social media promise a democratisation of the public sphere, but through algorithmic selection create filter bubbles that reinforce homogeneous opinion milieus.","options":["Soziale Medien versprechen eine Demokratisierung der Öffentlichkeit, schaffen jedoch durch algorithmische Selektion Filterblasen, die homogene Meinungsmilieus verstärken.","Soziale Medien können Demokratie fördern, aber auch gefährden.","Algorithmen bestimmen, welche Inhalte wir sehen, und schaffen Filterblasen.","Filterblasen entstehen, wenn Algorithmen uns immer ähnliche Inhalte zeigen."],"correctAnswer":"Soziale Medien versprechen eine Demokratisierung der Öffentlichkeit, schaffen jedoch durch algorithmische Selektion Filterblasen, die homogene Meinungsmilieus verstärken."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Medikament lindert die Symptome, hat gleichzeitig aber auch ___.","options":["Nebenwirkungen","Folgen","Risiken","Probleme"],"correctAnswer":"Nebenwirkungen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The reform improved efficiency but simultaneously also increased inequality","wordBankItems":["Die","Reform","verbesserte","die","Effizienz",",","erhöhte","gleichzeitig","aber","auch","die","Ungleichheit","."],"correctAnswer":"Die Reform verbesserte die Effizienz , erhöhte gleichzeitig aber auch die Ungleichheit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Verstärken'' means?","options":["to reinforce/amplify","to strengthen","to intensify","to increase"],"correctAnswer":"to reinforce/amplify"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000247',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss energy history at B2","Use Energiegeschichte vocabulary","Talk about the energy transition and fossil fuels"],"explanation":{"intro":"Energy history vocabulary covers the transition from biomass to fossil fuels and the modern energy transition at B2.","culturalNote":"Energiegeschichte: energy transitions: 1) Vorindustrielle Energiebasis (preindustrial — wood, wind, water), 2) Kohle (coal — industrial revolution), 3) Öl und Gas (20th century), 4) Energiewende (energy transition — German: wind, solar, nuclear phaseout). Germany unique: Atomausstieg (nuclear exit — decided after Chernobyl 1986, accelerated post-Fukushima 2011, completed 2023) + Kohleausstieg (coal phaseout planned 2038). Key concept: Dekarbonisierung (decarbonisation)."},"examples":[{"german":"Die Geschichte der Energie ist die Geschichte von Übergängen zu immer energiedichteren Trägern — von Holz zu Kohle zu Öl — eine Tendenz, die der aktuelle Übergang zu erneuerbaren Energien strukturell umkehrt.","english":"The history of energy is the history of transitions to ever more energy-dense carriers — from wood to coal to oil — a tendency that the current transition to renewable energies structurally reverses."},{"german":"Deutschlands Energiewende ist ein politisch ambitioniertes Experiment, das zeigt, ob ein hochindustrialisiertes Land seinen Energiebedarf gleichzeitig dekarbonisieren, sichern und bezahlbar halten kann.","english":"Germany''s energy transition is a politically ambitious experiment that shows whether a highly industrialised country can simultaneously decarbonise, secure, and keep affordable its energy demand."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss energy history, Germany''s Energiewende, and the energy transition at B2."}}',
'{"items":[{"word":"energiedicht","translation":"energy-dense","pronunciation":"en-er-GEE-dikht","example":"Energiedichte Träger."},{"word":"der Träger","translation":"carrier/medium","pronunciation":"dayr TRÄ-ger","example":"Energieträger."},{"word":"umkehren","translation":"to reverse","pronunciation":"OOM-kay-ren","example":"Eine Tendenz umkehren."},{"word":"ambitioniert","translation":"ambitious","pronunciation":"am-bi-tsyo-NEERT","example":"Politisch ambitioniert."},{"word":"hochindustrialisiert","translation":"highly industrialised","pronunciation":"hokh-in-doos-tree-ah-li-ZEERT","example":"Hochindustrialisiertes Land."},{"word":"dekarbonisieren","translation":"to decarbonise","pronunciation":"deh-kar-bo-ni-ZEER-en","example":"Energiebedarf dekarbonisieren."}]}',
'{"title":"Strukturell umkehren — to structurally reverse (reverse a deep pattern, not just a surface trend)","pattern":"etwas strukturell umkehren = to structurally reverse something (umkehren = to reverse/turn around — separable; strukturell adds that it''s a deep/systemic reversal)","explanation":"Strukturell umkehren = to structurally reverse (separable: kehrt...um, kehrte...um, hat...umgekehrt). Die aktuelle Transition kehrt diese Tendenz strukturell um = The current transition structurally reverses this tendency. Strukturell (structurally) specifies the depth — not a surface reversal but a systemic one. Umkehren without strukturell can be more everyday (turn around, reverse direction). Compare: umkehren (to reverse/turn around), sich umkehren (to reverse itself), rückgängig machen (to undo — often specific past action), invertieren (to invert — more mathematical).","examples":[{"sentence":"Die Reform kehrte das bisherige Muster strukturell um.","translation":"The reform structurally reversed the previous pattern."},{"sentence":"Die Digitalisierung kehrt traditionelle Wertschöpfungsketten um.","translation":"Digitalisation is reversing traditional value chains."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Energiedicht'' means?","options":["energy-dense","high-energy","energy-rich","power-dense"],"correctAnswer":"energy-dense"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The history of energy is the history of transitions to ever more energy-dense carriers — from wood to coal to oil — a tendency that the current transition to renewable energies structurally reverses.","options":["Die Geschichte der Energie ist die Geschichte von Übergängen zu immer energiedichteren Trägern — von Holz zu Kohle zu Öl — eine Tendenz, die der aktuelle Übergang zu erneuerbaren Energien strukturell umkehrt.","Energie wurde immer effizienter, bis die erneuerbare Revolution begann.","Von Holz zu Kohle zu Öl — die Energiegeschichte ist eine Geschichte von Übergängen.","Erneuerbare Energien kehren den historischen Trend zu fossilen Brennstoffen um."],"correctAnswer":"Die Geschichte der Energie ist die Geschichte von Übergängen zu immer energiedichteren Trägern — von Holz zu Kohle zu Öl — eine Tendenz, die der aktuelle Übergang zu erneuerbaren Energien strukturell umkehrt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Reform kehrte das bisherige Muster strukturell ___.","options":["um","ab","aus","durch"],"correctAnswer":"um"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Digitalisation is reversing traditional value chains","wordBankItems":["Die","Digitalisierung","kehrt","traditionelle","Wertschöpfungsketten","um","."],"correctAnswer":"Die Digitalisierung kehrt traditionelle Wertschöpfungsketten um ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ambitioniert'' means?","options":["ambitious","ambitious","aspiring","bold"],"correctAnswer":"ambitious"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000248',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of transport at B2","Use Transportgeschichte vocabulary","Talk about railways, automobiles, and aviation"],"explanation":{"intro":"Transport history vocabulary covers the development of railways, automobiles, aviation, and their social impact at B2.","culturalNote":"Transportgeschichte: key German milestones: Eisenbahn (railway — first German line Nürnberg-Fürth 1835), Automobil (Benz 1885, VW Beetle 1938), Autobahn (motorway — begun in NS era, became symbol of modernity), Lufthansa (founded 1955), Deutsche Bahn (privatisation debate). Key concepts: Verkehrswende (transport transition — towards public transport, cycling, away from car dominance), Decarbonisation of transport, Mobilitätswende. Germany: Stauland (country of traffic jams) — cultural significance of the car."},"examples":[{"german":"Die Eisenbahn gilt als die Schlüsseltechnologie der industriellen Revolution, da sie nicht nur den Transport, sondern auch die raumzeitliche Wahrnehmung, die Wirtschaftsstruktur und die Staatlichkeit grundlegend transformierte.","english":"The railway is regarded as the key technology of the industrial revolution, since it fundamentally transformed not only transport, but also the spatio-temporal perception, economic structure, and statehood."},{"german":"Das Auto hat das 20. Jahrhundert wie kein anderes Produkt geprägt — es formte Stadtstrukturen, definierte Freiheitsbegriffe und schuf eine Industrie, die Deutschland bis heute wirtschaftlich trägt.","english":"The car has shaped the 20th century like no other product — it formed urban structures, defined concepts of freedom, and created an industry that continues to sustain Germany economically today."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss transport history, Germany''s railway and automobile heritage, and Verkehrswende at B2."}}',
'{"items":[{"word":"raumzeitlich","translation":"spatio-temporal","pronunciation":"ROWM-tsyt-likh","example":"Raumzeitliche Wahrnehmung."},{"word":"die Wahrnehmung","translation":"perception","pronunciation":"dee VAHR-nay-moong","example":"Wahrnehmung transformieren."},{"word":"die Staatlichkeit","translation":"statehood","pronunciation":"dee SHTAHT-likh-kyt","example":"Staatlichkeit formen."},{"word":"prägen","translation":"to shape/characterise","pronunciation":"PRÄ-gen","example":"Das Jahrhundert prägen."},{"word":"der Freiheitsbegriff","translation":"concept of freedom","pronunciation":"dayr FRY-hyts-beh-grif","example":"Freiheitsbegriffe definieren."},{"word":"tragen","translation":"to sustain/support","pronunciation":"TRAH-gen","example":"Wirtschaftlich tragen."}]}',
'{"title":"Wie kein anderes X — like no other X (superlative comparison by uniqueness)","pattern":"etwas prägt Y wie kein anderes Z = something shaped Y like no other Z (emphatic superlative — nothing else in the category had the same impact)","explanation":"Wie kein anderes/andere/anderen + noun = like no other (emphasising unique impact or influence in a category). Das Auto prägte das 20. Jahrhundert wie kein anderes Produkt = The car shaped the 20th century like no other product. Wie kein anderer in the first position (fronted): Wie kein anderes Produkt hat das Auto das 20. Jahrhundert geprägt. Common in writing that wants to claim singular historical significance without using a literal superlative. Compare: mehr als jedes andere (more than any other — quantitative), ohne Vorbild (without precedent), einzigartig (unique — adjective).","examples":[{"sentence":"Shakespeare prägte die englische Sprache wie kein anderer Autor.","translation":"Shakespeare shaped the English language like no other author."},{"sentence":"Der Zweite Weltkrieg hat Europa wie kein anderes Ereignis verändert.","translation":"The Second World War changed Europe like no other event."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Raumzeitlich'' means?","options":["spatio-temporal","spatial-temporal","space-time","spatial"],"correctAnswer":"spatio-temporal"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The car has shaped the 20th century like no other product — it formed urban structures, defined concepts of freedom, and created an industry that continues to sustain Germany economically today.","options":["Das Auto hat das 20. Jahrhundert wie kein anderes Produkt geprägt — es formte Stadtstrukturen, definierte Freiheitsbegriffe und schuf eine Industrie, die Deutschland bis heute wirtschaftlich trägt.","Das Auto ist das wichtigste Produkt des 20. Jahrhunderts.","Kein anderes Produkt hat die Gesellschaft so verändert wie das Auto.","Das Auto prägte Stadtstrukturen, Freiheitsbegriffe und die Wirtschaft."],"correctAnswer":"Das Auto hat das 20. Jahrhundert wie kein anderes Produkt geprägt — es formte Stadtstrukturen, definierte Freiheitsbegriffe und schuf eine Industrie, die Deutschland bis heute wirtschaftlich trägt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Shakespeare prägte die englische Sprache wie kein anderer ___.","options":["Autor","Dichter","Schreiber","Künstler"],"correctAnswer":"Autor"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The Second World War changed Europe like no other event","wordBankItems":["Der","Zweite","Weltkrieg","hat","Europa","wie","kein","anderes","Ereignis","verändert","."],"correctAnswer":"Der Zweite Weltkrieg hat Europa wie kein anderes Ereignis verändert ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Prägen'' means?","options":["to shape/characterise","to influence","to mark","to define"],"correctAnswer":"to shape/characterise"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-000000000249',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of medicine at B2","Use Medizingeschichte vocabulary","Talk about medical revolutions and public health"],"explanation":{"intro":"Medical history vocabulary covers key discoveries, public health developments, and medical ethics at B2.","culturalNote":"Medizingeschichte: key milestones with German connection: Robert Koch (Tuberkulosebazillus 1882, Cholerabazillus, Koch''s Postulate), Rudolf Virchow (Zellularpathologie — cellular pathology), Paul Ehrlich (Chemotherapie, Salvarsan), Röntgen (X-rays 1895). Broader: Penicillin (Fleming 1928), Pockenausrottung (smallpox eradication 1980), DNA Struktur (Watson/Crick 1953). German ethics: NS-Medizinverbrechen (Nazi medical crimes — Nürnberger Ärzteprozess 1946), Nürnberger Kodex (Nuremberg Code 1947 — medical ethics)."},"examples":[{"german":"Robert Kochs Entdeckung der Krankheitserreger legte die mikrobiologische Grundlage der modernen Medizin und transformierte die öffentliche Gesundheitspolitik durch das Konzept der Infektionskontrolle.","english":"Robert Koch''s discovery of pathogens laid the microbiological foundation of modern medicine and transformed public health policy through the concept of infection control."},{"german":"Die Geschichte der Medizin ist nicht allein eine Erfolgsgeschichte technologischer Innovationen, sondern auch die Geschichte von Missbrauch, Zwangsexperimenten und der langsamen Durchsetzung medizinischer Ethik.","english":"The history of medicine is not solely a success story of technological innovations, but also the history of abuse, forced experiments, and the slow establishment of medical ethics."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss medical history, Koch''s discoveries, Nazi medical crimes, and medical ethics at B2."}}',
'{"items":[{"word":"der Krankheitserreger","translation":"pathogen","pronunciation":"dayr KRANK-hyts-er-ray-ger","example":"Krankheitserreger entdecken."},{"word":"mikrobiologisch","translation":"microbiological","pronunciation":"mi-kro-bi-o-LO-gish","example":"Mikrobiologische Grundlage."},{"word":"der Missbrauch","translation":"abuse","pronunciation":"dayr MIS-browkh","example":"Missbrauch in der Medizin."},{"word":"das Zwangsexperiment","translation":"forced experiment","pronunciation":"dahs TSVANGKS-eks-peh-ri-ment","example":"Zwangsexperimente."},{"word":"die Durchsetzung","translation":"establishment/enforcement","pronunciation":"dee DOORKH-zetsoong","example":"Durchsetzung von Ethik."},{"word":"allein","translation":"solely/alone","pronunciation":"a-LYN","example":"Nicht allein."}]}',
'{"title":"Nicht allein, sondern auch — not solely, but also (correcting an incomplete picture)","pattern":"nicht allein + A, sondern auch + B = not solely A, but also B (nicht allein = not only/not solely — slightly stronger than nicht nur, often in formal writing)","explanation":"Nicht allein ... sondern auch = not solely ... but also. Nicht allein eine Erfolgsgeschichte, sondern auch die Geschichte von Missbrauch = not solely a success story, but also the history of abuse. Nicht allein is a slightly more formal/literary alternative to nicht nur. Both introduce a second element that the first statement omitted. Compare: nicht nur ... sondern auch (standard not only...but also), nicht ausschließlich (not exclusively — similar), nicht lediglich (not merely — emphatic), geschweige denn (let alone — for impossible/absurd additions).","examples":[{"sentence":"Das Werk ist nicht allein ein literarisches Meisterwerk, sondern auch ein historisches Dokument.","translation":"The work is not solely a literary masterpiece, but also a historical document."},{"sentence":"Der Erfolg hängt nicht allein von Talent ab, sondern auch von harter Arbeit.","translation":"Success does not depend solely on talent, but also on hard work."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Der Krankheitserreger'' means?","options":["pathogen","disease agent","germ","microbe"],"correctAnswer":"pathogen"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The history of medicine is not solely a success story of technological innovations, but also the history of abuse, forced experiments, and the slow establishment of medical ethics.","options":["Die Geschichte der Medizin ist nicht allein eine Erfolgsgeschichte technologischer Innovationen, sondern auch die Geschichte von Missbrauch, Zwangsexperimenten und der langsamen Durchsetzung medizinischer Ethik.","Medizin hat nicht nur Gutes gebracht, sondern auch Schaden angerichtet.","NS-Medizin ist ein dunkles Kapitel der Medizingeschichte.","Medizinische Ethik entstand als Reaktion auf Missbrauch und Experimente."],"correctAnswer":"Die Geschichte der Medizin ist nicht allein eine Erfolgsgeschichte technologischer Innovationen, sondern auch die Geschichte von Missbrauch, Zwangsexperimenten und der langsamen Durchsetzung medizinischer Ethik."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Werk ist nicht allein ein literarisches Meisterwerk, sondern auch ein historisches ___.","options":["Dokument","Zeugnis","Beitrag","Stück"],"correctAnswer":"Dokument"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: Success does not depend solely on talent but also on hard work","wordBankItems":["Der","Erfolg","hängt","nicht","allein","von","Talent","ab",",","sondern","auch","von","harter","Arbeit","."],"correctAnswer":"Der Erfolg hängt nicht allein von Talent ab , sondern auch von harter Arbeit ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Die Durchsetzung'' means?","options":["establishment/enforcement","implementation","enforcement","assertion"],"correctAnswer":"establishment/enforcement"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000024a',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss history of computing at B2","Use Informatikgeschichte vocabulary","Talk about the development of computers and the internet"],"explanation":{"intro":"History of computing vocabulary covers the development of computers, software, and the internet at B2.","culturalNote":"Informatikgeschichte: key milestones: Konrad Zuse (Z3 — first programmable computer 1941 — Berlin), ENIAC (1945 US), Transistor (1947 Bell Labs), Intel (integrated circuits), Personal Computer (Apple 1984, IBM PC), World Wide Web (Tim Berners-Lee 1989/1991 — CERN), Smartphone (iPhone 2007). German contributions: Zuse, SAP (enterprise software — founded 1972 Walldorf), Fraunhofer MP3. Key concepts: Digitalisierung, KI (artificial intelligence), Machine Learning, Big Data."},"examples":[{"german":"Konrad Zuses Pionierleistungen bei der Entwicklung des programmierbaren Computers in Berlin finden im internationalen Gedächtnis der Computergeschichte weniger Anerkennung, als sie verdienen würden.","english":"Konrad Zuse''s pioneering achievements in developing the programmable computer in Berlin receive less recognition in the international memory of computer history than they would deserve."},{"german":"Die Entstehung des World Wide Web verwandelte das Internet von einem Werkzeug für Wissenschaftler und Militärangehörige in eine allgemein zugängliche Kommunikations- und Informationsinfrastruktur.","english":"The emergence of the World Wide Web transformed the internet from a tool for scientists and military personnel into a universally accessible communication and information infrastructure."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss computing history, Konrad Zuse, and the internet''s development at B2."}}',
'{"items":[{"word":"die Pionierleistung","translation":"pioneering achievement","pronunciation":"dee pyo-NEER-lys-toong","example":"Pionierleistungen."},{"word":"programmierbar","translation":"programmable","pronunciation":"pro-gra-MEER-bahr","example":"Programmierbarer Computer."},{"word":"verwandeln in","translation":"to transform into","pronunciation":"fer-VAN-deln in","example":"In ein Werkzeug verwandeln."},{"word":"zugänglich","translation":"accessible","pronunciation":"TSOO-geng-likh","example":"Allgemein zugänglich."},{"word":"die Infrastruktur","translation":"infrastructure","pronunciation":"dee in-frah-shtrook-TOOR","example":"Kommunikationsinfrastruktur."},{"word":"verdienen","translation":"to deserve","pronunciation":"fer-DEE-nen","example":"Anerkennung verdienen."}]}',
'{"title":"Weniger ... als sie verdienen würden — less than they deserve (counterfactual regret)","pattern":"etwas erhält weniger X als es Y verdienen würde = something receives less X than it would deserve (Konjunktiv II — counterfactual: the situation could/should be different)","explanation":"Als sie/es ... verdienen würden/würde = than they/it would deserve (Konjunktiv II of verdienen — verdienen würden/würde, because the deserving is potential, not actual). The whole construction X erhält weniger Y als es verdienen würde = X receives less Y than it would deserve (comparative counterfactual — reality falls short of what is merited). Pattern: [Subject] erhält/findet weniger [Noun] als [Subject] verdienen würde. Compare: mehr/besser als erwartet (better than expected — actual vs. prior expectation), sollte eigentlich (should really — moral claim), es wäre angemessener (it would be more appropriate).","examples":[{"sentence":"Der Künstler bekommt weniger Aufmerksamkeit, als er verdienen würde.","translation":"The artist receives less attention than he would deserve."},{"sentence":"Diese Entdeckung findet in der Öffentlichkeit weniger Beachtung, als sie verdienen würde.","translation":"This discovery receives less public attention than it would deserve."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Pionierleistung'' means?","options":["pioneering achievement","pioneering work","groundbreaking contribution","first-mover achievement"],"correctAnswer":"pioneering achievement"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"Konrad Zuse''s pioneering achievements in developing the programmable computer in Berlin receive less recognition in the international memory of computer history than they would deserve.","options":["Konrad Zuses Pionierleistungen bei der Entwicklung des programmierbaren Computers in Berlin finden im internationalen Gedächtnis der Computergeschichte weniger Anerkennung, als sie verdienen würden.","Konrad Zuse ist zu wenig bekannt für seine Beiträge zur Computergeschichte.","Zuses Erfindungen werden international zu wenig anerkannt.","Deutschland hat mit Zuse einen wichtigen Beitrag zur Computergeschichte geleistet."],"correctAnswer":"Konrad Zuses Pionierleistungen bei der Entwicklung des programmierbaren Computers in Berlin finden im internationalen Gedächtnis der Computergeschichte weniger Anerkennung, als sie verdienen würden."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Der Künstler bekommt weniger Aufmerksamkeit, als er verdienen ___.","options":["würde","sollte","könnte","müsste"],"correctAnswer":"würde"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: This discovery receives less public attention than it would deserve","wordBankItems":["Diese","Entdeckung","findet","in","der","Öffentlichkeit","weniger","Beachtung",",","als","sie","verdienen","würde","."],"correctAnswer":"Diese Entdeckung findet in der Öffentlichkeit weniger Beachtung , als sie verdienen würde ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Zugänglich'' means?","options":["accessible","available","open","reachable"],"correctAnswer":"accessible"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000024b',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss space exploration at B2","Use Raumfahrt vocabulary","Talk about German and European space history"],"explanation":{"intro":"Space exploration vocabulary covers rocket technology, key missions, and German/European space programmes at B2.","culturalNote":"Raumfahrt mit deutschem Bezug: V2-Rakete (Wernher von Braun — Peenemünde, later NASA), ESA (Europäische Weltraumorganisation — European Space Agency, founded 1975, Cologne headquarters of ESAC), DLR (Deutsches Zentrum für Luft- und Raumfahrt). Key missions: Apollo (1969 Moon landing), ISS (International Space Station — German astronauts: Thomas Reiter, Alexander Gerst — ''Astro-Alex''), Hubble, Mars missions. ESA missions: Rosetta (comet landing 2014), Ariane launcher."},"examples":[{"german":"Die Entwicklung der V2-Rakete im Zweiten Weltkrieg bildet eine technologische Keimzelle der zivilen Raumfahrt, verbindet aber zugleich die Ursprünge der Weltraumtechnik untrennbar mit Zwangsarbeit und Kriegsverbrechen.","english":"The development of the V2 rocket in the Second World War forms a technological seed cell of civilian space flight, but at the same time inseparably links the origins of space technology with forced labour and war crimes."},{"german":"Die internationale Raumstation ISS steht für ein Kooperationsmodell, das zeigt, wie Länder in einem technologisch anspruchsvollen Projekt zusammenarbeiten können, selbst wenn sie politisch in Konkurrenz stehen.","english":"The International Space Station ISS stands for a model of cooperation that shows how countries can work together on a technologically demanding project, even when they are in political competition."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss space exploration, German space history, and international space cooperation at B2."}}',
'{"items":[{"word":"die Keimzelle","translation":"seed cell/nucleus","pronunciation":"dee KYM-tsel-eh","example":"Technologische Keimzelle."},{"word":"untrennbar","translation":"inseparably","pronunciation":"oon-TREN-bahr","example":"Untrennbar verbunden."},{"word":"anspruchsvoll","translation":"demanding/sophisticated","pronunciation":"AN-shproookhs-fol","example":"Technisch anspruchsvoll."},{"word":"selbst wenn","translation":"even when/even if","pronunciation":"zelp-st ven","example":"Selbst wenn sie konkurrieren."},{"word":"die Konkurrenz","translation":"competition","pronunciation":"dee kon-koo-RENTS","example":"In Konkurrenz stehen."},{"word":"das Kooperationsmodell","translation":"model of cooperation","pronunciation":"dahs ko-o-peh-rah-TSYOHNS-mo-del","example":"Kooperationsmodell."}]}',
'{"title":"Untrennbar verbunden mit — inseparably linked with (permanent association)","pattern":"etwas ist untrennbar mit etwas verbunden = something is inseparably linked with something (the two cannot be separated — untrennbar = inseparable, from trennen = to separate)","explanation":"Untrennbar mit etwas verbunden = inseparably linked with (the two things cannot be thought of apart from each other). Die Ursprünge sind untrennbar mit Zwangsarbeit verbunden = The origins are inseparably linked with forced labour. Passive with sein + Partizip II adjective (verbunden). Compare: eng mit etwas verbunden (closely connected with — less absolute), verknüpft mit (linked with — more neutral), nicht von X zu trennen (not to be separated from X — similar, more verbal), einhergehen mit (to go along with — process rather than permanent state).","examples":[{"sentence":"Die Kunstgeschichte der Renaissance ist untrennbar mit dem Mäzenatentum verbunden.","translation":"The art history of the Renaissance is inseparably linked with patronage."},{"sentence":"Sein Name ist untrennbar mit dieser Entdeckung verbunden.","translation":"His name is inseparably linked with this discovery."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Keimzelle'' means?","options":["seed cell/nucleus","germ cell","embryo","origin point"],"correctAnswer":"seed cell/nucleus"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The development of the V2 rocket in the Second World War forms a technological seed cell of civilian space flight, but at the same time inseparably links the origins of space technology with forced labour and war crimes.","options":["Die Entwicklung der V2-Rakete im Zweiten Weltkrieg bildet eine technologische Keimzelle der zivilen Raumfahrt, verbindet aber zugleich die Ursprünge der Weltraumtechnik untrennbar mit Zwangsarbeit und Kriegsverbrechen.","Die V2-Rakete war eine Vorbedingung für die zivile Raumfahrt.","Raumfahrttechnik hat ihre Ursprünge in militärischen Raketen aus dem Zweiten Weltkrieg.","Die Raumfahrt verbindet technologischen Fortschritt mit einer dunklen Vergangenheit."],"correctAnswer":"Die Entwicklung der V2-Rakete im Zweiten Weltkrieg bildet eine technologische Keimzelle der zivilen Raumfahrt, verbindet aber zugleich die Ursprünge der Weltraumtechnik untrennbar mit Zwangsarbeit und Kriegsverbrechen."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Sein Name ist untrennbar mit dieser Entdeckung ___.","options":["verbunden","verknüpft","assoziiert","versehen"],"correctAnswer":"verbunden"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The art history of the Renaissance is inseparably linked with patronage","wordBankItems":["Die","Kunstgeschichte","der","Renaissance","ist","untrennbar","mit","dem","Mäzenatentum","verbunden","."],"correctAnswer":"Die Kunstgeschichte der Renaissance ist untrennbar mit dem Mäzenatentum verbunden ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Anspruchsvoll'' means?","options":["demanding/sophisticated","challenging","complex","difficult"],"correctAnswer":"demanding/sophisticated"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000024c',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss telecommunications at B2","Use Telekommunikation vocabulary","Talk about the history of communication technology"],"explanation":{"intro":"Telecommunications vocabulary covers the development from telegraph to mobile phones and the digital age at B2.","culturalNote":"Telekommunikationsgeschichte: Telegraf (Morse 1837 — first long-distance fast communication), Telefon (Bell 1876 — and Philipp Reis 1861 Germany), Radio (Hertz — German), Fernsehen (television — first regular broadcast Germany 1935), Internet (1969 ARPANET), Mobiltelefon (Handy — Germany — first mobile call 1958), Smartphone (2007). Deutsche Telekom (formerly Bundespost — privatised 1995). Key debate: Netzausbau (network expansion), 5G, digitale Teilhabe (digital inclusion vs. exclusion)."},"examples":[{"german":"Die Geschichte der Telekommunikation lässt sich als kontinuierliche Überwindung von Raum und Zeit beschreiben: Jede neue Technologie komprimierte die Entfernung zwischen Menschen weiter.","english":"The history of telecommunications can be described as a continuous overcoming of space and time: each new technology further compressed the distance between people."},{"german":"Die Konvergenz von Telefon, Kamera, Computer und Internet in einem einzigen mobilen Gerät hat nicht nur die Kommunikation, sondern die gesamte soziale und wirtschaftliche Organisation von Gesellschaften verändert.","english":"The convergence of telephone, camera, computer, and internet in a single mobile device has changed not only communication, but the entire social and economic organisation of societies."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss telecommunications history, key inventions, and convergence at B2."}}',
'{"items":[{"word":"die Überwindung","translation":"overcoming","pronunciation":"dee ü-ber-VIN-doong","example":"Überwindung von Entfernung."},{"word":"komprimieren","translation":"to compress","pronunciation":"kom-pri-MEER-en","example":"Entfernungen komprimieren."},{"word":"die Konvergenz","translation":"convergence","pronunciation":"dee kon-ver-GENTS","example":"Konvergenz von Technologien."},{"word":"kontinuierlich","translation":"continuous/continual","pronunciation":"kon-ti-noo-EER-likh","example":"Kontinuierliche Überwindung."},{"word":"sich beschreiben lassen als","translation":"to be describable as","pronunciation":"zikh beh-SHRY-ben la-sen als","example":"Als X beschreiben lassen."},{"word":"das Gerät","translation":"device","pronunciation":"dahs geh-RÄT","example":"Mobiles Gerät."}]}',
'{"title":"Sich als X beschreiben lassen — to be describable as X (can be described as X)","pattern":"etwas lässt sich als X beschreiben = something can be described as X / is describable as X (sich lassen + infinitive = can, is possible to — applies to things that CAN be described)","explanation":"Sich als X beschreiben lassen = to be describable as X (lassen + sich + infinitive = can/may + passive meaning for possibilities). Die Geschichte lässt sich als Überwindung beschreiben = The history can be described as an overcoming. This modal construction (lassen + reflexive + infinitive) expresses possibility: etwas lässt sich tun = something can be done / is doable. Formal alternative to: kann als X beschrieben werden (can be described as X — passive). Also: lässt sich erklären (can be explained), lässt sich nachweisen (can be demonstrated), lässt sich vermeiden (can be avoided).","examples":[{"sentence":"Das Problem lässt sich nicht einfach lösen.","translation":"The problem cannot simply be solved."},{"sentence":"Die Situation lässt sich als Dilemma beschreiben.","translation":"The situation can be described as a dilemma."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Konvergenz'' means?","options":["convergence","merger","integration","fusion"],"correctAnswer":"convergence"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The history of telecommunications can be described as a continuous overcoming of space and time: each new technology further compressed the distance between people.","options":["Die Geschichte der Telekommunikation lässt sich als kontinuierliche Überwindung von Raum und Zeit beschreiben: Jede neue Technologie komprimierte die Entfernung zwischen Menschen weiter.","Telekommunikation macht die Welt kleiner und näher.","Jede neue Kommunikationstechnologie verändert die menschliche Wahrnehmung von Distanz.","Die Geschichte der Telekommunikation ist eine Abfolge von Revolutionen."],"correctAnswer":"Die Geschichte der Telekommunikation lässt sich als kontinuierliche Überwindung von Raum und Zeit beschreiben: Jede neue Technologie komprimierte die Entfernung zwischen Menschen weiter."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Das Problem lässt sich nicht einfach ___.","options":["lösen","beheben","klären","bewältigen"],"correctAnswer":"lösen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The situation can be described as a dilemma","wordBankItems":["Die","Situation","lässt","sich","als","Dilemma","beschreiben","."],"correctAnswer":"Die Situation lässt sich als Dilemma beschreiben ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Kontinuierlich'' means?","options":["continuous/continual","constant","ongoing","uninterrupted"],"correctAnswer":"continuous/continual"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000024d',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss engineering at B2","Use Ingenieurwesen vocabulary","Talk about German engineering and industrial design"],"explanation":{"intro":"Engineering vocabulary covers disciplines, German engineering culture, and the relationship between technology and society at B2.","culturalNote":"Ingenieurwesen in Germany: Ingenieur (engineer) has high social prestige. Key disciplines: Maschinenbau (mechanical engineering), Elektrotechnik (electrical engineering), Bauingenieurwesen (civil engineering), Verfahrenstechnik (chemical engineering). German engineering culture: Qualität Made in Germany (quality label since 1887, initially derogatory British label), Präzision und Gründlichkeit (precision and thoroughness), Berufsausbildung (dual vocational system — apprenticeship + school). Key institutions: TU München, RWTH Aachen. VDE, VDI (engineering associations)."},"examples":[{"german":"Das Gütesiegel ''Made in Germany'' ist paradoxerweise als britischer Warnhinweis entstanden und hat sich zu einem der wertvollsten Markenzeichen für Qualität und Verlässlichkeit in der Weltwirtschaft entwickelt.","english":"The quality seal ''Made in Germany'' was paradoxically created as a British warning label and has developed into one of the most valuable brand marks for quality and reliability in the world economy."},{"german":"Ingenieurwesen verbindet naturwissenschaftliche Erkenntnis mit praktischer Problemlösung unter Einbeziehung ökonomischer, sozialer und ethischer Rahmenbedingungen.","english":"Engineering combines scientific knowledge with practical problem-solving, incorporating economic, social, and ethical framework conditions."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss German engineering culture, Made in Germany, and engineering disciplines at B2."}}',
'{"items":[{"word":"das Gütesiegel","translation":"quality seal","pronunciation":"dahs GÜ-teh-zee-gel","example":"Gütesiegel der Qualität."},{"word":"paradoxerweise","translation":"paradoxically","pronunciation":"pah-rah-DOK-ser-vy-seh","example":"Paradoxerweise entstanden."},{"word":"das Markenzeichen","translation":"brand mark/trademark","pronunciation":"dahs MAR-ken-tsy-khen","example":"Wertvolles Markenzeichen."},{"word":"die Verlässlichkeit","translation":"reliability","pronunciation":"dee fer-LES-likh-kyt","example":"Qualität und Verlässlichkeit."},{"word":"die Rahmenbedingung","translation":"framework condition","pronunciation":"dee RAH-men-beh-din-goong","example":"Ökonomische Rahmenbedingungen."},{"word":"unter Einbeziehung von","translation":"incorporating/taking into account","pronunciation":"oon-ter YN-beh-tsee-oong fon","example":"Unter Einbeziehung aller Aspekte."}]}',
'{"title":"Unter Einbeziehung von — incorporating, taking into account (inclusive of additional factors)","pattern":"etwas geschieht/entsteht unter Einbeziehung von X = something happens incorporating X, taking X into account (nominalized infinitive from einbeziehen — to include/incorporate)","explanation":"Unter Einbeziehung von + noun/dative = incorporating, taking into account (formal — used in academic, technical, or policy writing). Ingenieurwesen verbindet X mit Y unter Einbeziehung Z = Engineering combines X with Y, incorporating Z. Nominalization of einbeziehen (to include/involve). Alternative: unter Berücksichtigung (taking into account — similar, more neutral), in Verbindung mit (in conjunction with), einschließlich (including — simpler).","examples":[{"sentence":"Die Entscheidung wurde unter Einbeziehung aller Stakeholder getroffen.","translation":"The decision was made incorporating all stakeholders."},{"sentence":"Das Projekt wurde unter Einbeziehung aktueller Forschungsergebnisse entwickelt.","translation":"The project was developed taking into account current research findings."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Verlässlichkeit'' means?","options":["reliability","dependability","trustworthiness","consistency"],"correctAnswer":"reliability"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The quality seal ''Made in Germany'' was paradoxically created as a British warning label and has developed into one of the most valuable brand marks for quality and reliability in the world economy.","options":["Das Gütesiegel ''Made in Germany'' ist paradoxerweise als britischer Warnhinweis entstanden und hat sich zu einem der wertvollsten Markenzeichen für Qualität und Verlässlichkeit in der Weltwirtschaft entwickelt.","Made in Germany steht für Qualität und ist weltweit bekannt.","Das britische Label ''Made in Germany'' wurde zu einem positiven Qualitätsmerkmal.","Germany''s Exportprodukte gelten als hochwertig und zuverlässig."],"correctAnswer":"Das Gütesiegel ''Made in Germany'' ist paradoxerweise als britischer Warnhinweis entstanden und hat sich zu einem der wertvollsten Markenzeichen für Qualität und Verlässlichkeit in der Weltwirtschaft entwickelt."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Die Entscheidung wurde unter Einbeziehung aller Stakeholder ___.","options":["getroffen","gemacht","gefällt","entschieden"],"correctAnswer":"getroffen"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: The project was developed taking into account current research findings","wordBankItems":["Das","Projekt","wurde","unter","Einbeziehung","aktueller","Forschungsergebnisse","entwickelt","."],"correctAnswer":"Das Projekt wurde unter Einbeziehung aktueller Forschungsergebnisse entwickelt ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Paradoxerweise'' means?","options":["paradoxically","ironically","strangely","counterintuitively"],"correctAnswer":"paradoxically"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

INSERT INTO cf_lesson_versions (lesson_id,version,content_status,publication_status,content,vocabulary,grammar,exercises,frozen,published_at) VALUES
('aa000000-0000-0000-0000-00000000024e',1,'APPROVED','PUBLISHED',
'{"objectives":["Discuss technology assessment at B2","Use Technologiefolgenabschätzung vocabulary","Talk about risks and benefits of new technologies"],"explanation":{"intro":"Technology assessment vocabulary covers the systematic evaluation of technologies'' societal impacts at B2.","culturalNote":"Technologiefolgenabschätzung (TA): systematic evaluation of technologies for societal, ethical, and environmental impacts. Germany has: Büro für Technikfolgen-Abschätzung (TAB — parliamentary technology assessment body, since 1990). Key concept: Vorsorgeprinzip (precautionary principle — if uncertain about harm, err on side of caution — embedded in EU law). Application areas: Gentechnik (genetic engineering), KI, Kernkraft, Medizintechnik. Germany''s ambivalent relationship with technology: technikfreundlich (pro-technology — engineers) vs. Technikskepsis (skeptical — environmentalists, public)."},"examples":[{"german":"Das Vorsorgeprinzip verlangt, dass bei wissenschaftlicher Ungewissheit über potenzielle Schadensfolgen einer Technologie der Schutz der Gesellschaft Vorrang vor wirtschaftlichen Interessen hat.","english":"The precautionary principle requires that in the face of scientific uncertainty about potential harmful consequences of a technology, the protection of society takes priority over economic interests."},{"german":"Technologiefolgenabschätzung zielt nicht darauf ab, den technischen Fortschritt zu bremsen, sondern Entscheidungsträger mit dem Wissen auszustatten, das für eine verantwortungsvolle Gestaltung von Innovationen notwendig ist.","english":"Technology assessment does not aim to slow down technical progress, but to equip decision-makers with the knowledge that is necessary for the responsible shaping of innovations."}],"rewards":{"xp":150,"coins":80},"metadata":{"estimatedMinutes":20,"canDo":"I can discuss technology assessment, the precautionary principle, and technology governance at B2."}}',
'{"items":[{"word":"die Ungewissheit","translation":"uncertainty","pronunciation":"dee oon-geh-VIS-hyt","example":"Wissenschaftliche Ungewissheit."},{"word":"der Vorrang","translation":"priority/precedence","pronunciation":"dayr FOR-rang","example":"Vorrang haben."},{"word":"ausstatten mit","translation":"to equip with","pronunciation":"OWS-shtat-en mit","example":"Mit Wissen ausstatten."},{"word":"die Gestaltung","translation":"shaping/design","pronunciation":"dee geh-SHTAL-toong","example":"Verantwortungsvolle Gestaltung."},{"word":"verantwortungsvoll","translation":"responsible","pronunciation":"fer-ANT-vort-oonks-fol","example":"Verantwortungsvoller Umgang."},{"word":"das Vorsorgeprinzip","translation":"precautionary principle","pronunciation":"dahs FOR-zor-geh-prin-tsip","example":"Vorsorgeprinzip."}]}',
'{"title":"Vorrang haben vor — to take priority over (one thing has higher priority than another)","pattern":"A hat Vorrang vor B = A takes priority over B (Vorrang = priority/precedence — Vor + Rang — in front in rank)","explanation":"Vorrang haben vor + dative = to take priority over, to take precedence over. Der Schutz der Gesellschaft hat Vorrang vor wirtschaftlichen Interessen = The protection of society takes priority over economic interests. Also: Vorrang einräumen (to give priority to — transitive), Vorrang geben (to give priority), prioritär behandeln (to treat as priority). Compare: wichtiger sein als (to be more important than — more direct), überwiegen (to outweigh — more about weight), den Ausschlag geben (to tip the scales — more decisive factor).","examples":[{"sentence":"In einer Notlage hat die Sicherheit aller Vorrang vor individuellen Interessen.","translation":"In an emergency, the safety of all takes priority over individual interests."},{"sentence":"Qualität sollte Vorrang vor Quantität haben.","translation":"Quality should take priority over quantity."}]}',
'{"items":[{"id":"ex1","type":"MULTIPLE_CHOICE","question":"''Die Ungewissheit'' means?","options":["uncertainty","doubt","ambiguity","indecision"],"correctAnswer":"uncertainty"},{"id":"ex2","type":"TRANSLATE_TO_TARGET","question":"The precautionary principle requires that in the face of scientific uncertainty about potential harmful consequences of a technology, the protection of society takes priority over economic interests.","options":["Das Vorsorgeprinzip verlangt, dass bei wissenschaftlicher Ungewissheit über potenzielle Schadensfolgen einer Technologie der Schutz der Gesellschaft Vorrang vor wirtschaftlichen Interessen hat.","Das Vorsorgeprinzip stellt den gesellschaftlichen Schutz über wirtschaftliche Interessen.","Bei unsicheren Technologien sollte Vorsicht Vorrang haben.","Gesellschaftliche Sicherheit hat Priorität vor Wirtschaftswachstum."],"correctAnswer":"Das Vorsorgeprinzip verlangt, dass bei wissenschaftlicher Ungewissheit über potenzielle Schadensfolgen einer Technologie der Schutz der Gesellschaft Vorrang vor wirtschaftlichen Interessen hat."},{"id":"ex3","type":"FILL_IN_BLANK","question":"Qualität sollte Vorrang vor Quantität ___.","options":["haben","besitzen","genießen","vorweisen"],"correctAnswer":"haben"},{"id":"ex4","type":"SENTENCE_CONSTRUCT","question":"Build: In an emergency the safety of all takes priority over individual interests","wordBankItems":["In","einer","Notlage","hat","die","Sicherheit","aller","Vorrang","vor","individuellen","Interessen","."],"correctAnswer":"In einer Notlage hat die Sicherheit aller Vorrang vor individuellen Interessen ."},{"id":"ex5","type":"MULTIPLE_CHOICE","question":"''Ausstatten mit'' means?","options":["to equip with","to provide with","to supply with","to furnish with"],"correctAnswer":"to equip with"}]}'::jsonb,
true,NOW()) ON CONFLICT (lesson_id,version) DO NOTHING;

